#!/usr/bin/env node
/**
 * The GitHub Action's runner (action.yml), also usable on its own:
 *
 *   node actions/fitness-api-deprecation-check/run.mjs [paths...] [--fail-on error|warning|never] [--json]
 *
 * Walks the given files and directories, runs dist/scan.mjs with
 * dist/rules.json over each text file, and reports every hit: as workflow
 * annotations and a job summary inside GitHub Actions, as plain lines
 * elsewhere. Zero dependencies; nothing leaves the machine.
 *
 * dist/ is generated by scripts/build-deprecation-rules.mjs in
 * nikitastarovzz/aifitnessapi; this file is hand-written.
 */
import fs from "node:fs";
import path from "node:path";
import { annotation, compileRules, describeHits, fileContext, hitMessage, scanText, summarize, todayUtc } from "./dist/scan.mjs";

const HERE = import.meta.dirname;
const bundle = JSON.parse(fs.readFileSync(path.join(HERE, "dist/rules.json"), "utf8"));

const SKIP_DIRS = new Set([".git", "node_modules", ".next", "dist", "build", "out", "vendor", "Pods", ".gradle", "venv", ".venv", "__pycache__", "target", "coverage", ".turbo", ".cache"]);
const MAX_BYTES = 2 * 1024 * 1024;

function parseArgs(argv, env) {
  const opts = { paths: [], exclude: [], failOn: env.FADC_FAIL_ON || "error", json: false, today: env.FADC_TODAY || todayUtc() };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--fail-on") opts.failOn = argv[++i];
    else if (a === "--exclude") opts.exclude.push(argv[++i]);
    else if (a === "--json") opts.json = true;
    else opts.paths.push(a);
  }
  const split = (s) => String(s ?? "").split(/\s+/).filter(Boolean);
  if (!opts.paths.length) opts.paths = split(env.FADC_PATH);
  if (!opts.paths.length) opts.paths = ["."];
  opts.exclude.push(...split(env.FADC_EXCLUDE));
  if (!["error", "warning", "never"].includes(opts.failOn)) throw new Error(`fail-on must be error, warning or never (got ${opts.failOn})`);
  return opts;
}

/** Every file under the given paths, skipping dependency and build folders. */
export function listFiles(paths, exclude = []) {
  const norm = (p) => path.normalize(p).replace(/\\/g, "/").replace(/^\.\//, "");
  const ex = exclude.map((e) => norm(e).replace(/\/$/, ""));
  const skipped = (p) => ex.some((e) => p === e || p.startsWith(`${e}/`));
  const out = [];
  const walk = (p) => {
    const rel = norm(p);
    if (skipped(rel)) return;
    let st;
    try {
      st = fs.statSync(p);
    } catch {
      return;
    }
    if (st.isDirectory()) {
      for (const name of fs.readdirSync(p).sort()) {
        if (SKIP_DIRS.has(name)) continue;
        walk(path.join(p, name));
      }
    } else if (st.isFile() && st.size <= MAX_BYTES) out.push(rel);
  };
  for (const p of paths) walk(p);
  return [...new Set(out)];
}

function readText(file) {
  const buf = fs.readFileSync(file);
  if (buf.subarray(0, 8000).includes(0)) return null; // binary
  return buf.toString("utf8");
}

/** Scan files; returns described hits with their file. */
export function scanFiles(files, today) {
  const compiled = compileRules(bundle);
  const all = [];
  for (const file of files) {
    const text = readText(file);
    if (text == null) continue;
    const hits = scanText(text, { compiled, context: fileContext(file) });
    for (const d of describeHits(hits, bundle, today)) all.push({ file, ...d });
  }
  return all;
}

function mdCell(s) {
  return String(s).replace(/\|/g, "\\|").replace(/\n/g, " ");
}

function summaryMarkdown(found, sum) {
  const site = bundle.site;
  const lines = [
    "## Fitness API deprecation check",
    "",
    sum.total
      ? `${sum.total} reference${sum.total === 1 ? "" : "s"}: ${sum.errors} to APIs that are gone or past their end date, ${sum.warnings} to deprecated or dying ones.`
      : "No references to the deprecated or shut-down APIs this check knows.",
    "",
  ];
  if (sum.total) {
    lines.push("| Where | What | Status | Replacement |", "|---|---|---|---|");
    for (const d of found) {
      const e = d.entry;
      const when = e.end ? `${e.endLabel}: ${e.endText}` : e.endLabel;
      const repl = d.rule.replacement.length ? d.rule.replacement.map((r) => (r.href ? `[${r.label}](${site}${r.href})` : r.label)).join("; ") : "None named by the vendor";
      const mig = e.migrate ? ` ([migration](${site}${e.migrate.href}))` : "";
      lines.push(`| \`${mdCell(d.file)}:${d.line}\` | ${mdCell(d.rule.label)} | ${mdCell(`${e.statusLabel}. ${when}`)} | ${mdCell(repl)}${mig} |`);
    }
    lines.push("");
  }
  lines.push(`Rules from [${site.replace(/^https:\/\//, "")}](${site}/tools/deprecation-scanner), built ${bundle.updated}: ${bundle.counts.rules} patterns over ${bundle.counts.entries} retired APIs, each quoted from its vendor.`, "");
  return lines.join("\n");
}

function main() {
  const env = process.env;
  const opts = parseArgs(process.argv.slice(2), env);
  const files = listFiles(opts.paths, opts.exclude);
  const found = scanFiles(files, opts.today);
  const sum = summarize(found);
  const inActions = env.GITHUB_ACTIONS === "true";

  if (opts.json) {
    console.log(JSON.stringify({ files: files.length, ...sum, hits: found.map((d) => ({ file: d.file, line: d.line, column: d.column, rule: d.rule.id, entry: d.entry.id, severity: d.severity.level, match: d.match })) }, null, 2));
  } else {
    for (const d of found) {
      if (inActions) console.log(annotation(d, d.file, bundle.site));
      else console.log(`${d.file}:${d.line}:${d.column} ${d.severity.level}: ${hitMessage(d)}`);
    }
    console.log(`fitness-api-deprecation-check: ${files.length} files, ${sum.total} hits (${sum.errors} errors, ${sum.warnings} warnings)`);
  }
  if (env.GITHUB_STEP_SUMMARY) fs.appendFileSync(env.GITHUB_STEP_SUMMARY, summaryMarkdown(found, sum));
  if (env.GITHUB_OUTPUT) fs.appendFileSync(env.GITHUB_OUTPUT, `hits=${sum.total}\nerrors=${sum.errors}\nwarnings=${sum.warnings}\n`);
  const failed = opts.failOn === "warning" ? sum.total > 0 : opts.failOn === "error" ? sum.errors > 0 : false;
  process.exitCode = failed ? 1 : 0;
}

if (import.meta.url === `file://${process.argv[1]}` || process.argv[1]?.endsWith("run.mjs")) main();
